-- ============================================================
-- ECOAGRIS ECOWAS DATA IMPORT
-- Generated from validated Excel datasets
-- ============================================================

BEGIN;


-- ============================================================
-- Agricultural Inputs: 300 records
-- ============================================================


ON CONFLICT (country_id, year) DO UPDATE SET
    cereal_seeds_tons = EXCLUDED.cereal_seeds_tons, fertilizer_tons = EXCLUDED.fertilizer_tons, pesticide_liters = EXCLUDED.pesticide_liters, improved_seed_use_pct = EXCLUDED.improved_seed_use_pct, fertilizer_kg_per_ha = EXCLUDED.fertilizer_kg_per_ha, input_price_index_2006_base = EXCLUDED.input_price_index_2006_base, agro_dealer_count = EXCLUDED.agro_dealer_count, input_subsidy_budget_usd = EXCLUDED.input_subsidy_budget_usd, distribution_timeliness_pct = EXCLUDED.distribution_timeliness_pct, stockouts_days_per_year = EXCLUDED.stockouts_days_per_year, input_import_value_usd = EXCLUDED.input_import_value_usd, local_production_inputs_tons = EXCLUDED.local_production_inputs_tons, mechanization_units_per_1000_farms = EXCLUDED.mechanization_units_per_1000_farms, credit_access_pct = EXCLUDED.credit_access_pct;

-- ============================================================
-- Livestock: 300 records
-- ============================================================


ON CONFLICT (country_id, year) DO UPDATE SET
    cattle_head = EXCLUDED.cattle_head, small_ruminants_head = EXCLUDED.small_ruminants_head, pigs_head = EXCLUDED.pigs_head, poultry_head = EXCLUDED.poultry_head, milk_production_tons = EXCLUDED.milk_production_tons, meat_production_tons = EXCLUDED.meat_production_tons, livestock_price_index_2006_base = EXCLUDED.livestock_price_index_2006_base, vaccination_coverage_pct = EXCLUDED.vaccination_coverage_pct, fmd_incidents_count = EXCLUDED.fmd_incidents_count, grazing_area_ha = EXCLUDED.grazing_area_ha, transhumance_events = EXCLUDED.transhumance_events, veterinary_facilities_count = EXCLUDED.veterinary_facilities_count, feed_imports_tons = EXCLUDED.feed_imports_tons, local_feed_production_tons = EXCLUDED.local_feed_production_tons, livestock_exports_tons = EXCLUDED.livestock_exports_tons, offtake_rate_pct = EXCLUDED.offtake_rate_pct;


COMMIT;
